import java.util.Scanner;

public class Main {
    static long n;
    static long[] A = new long[21];
    static long[] B = new long[21];
    static long min_cost;

    static void recurse(int position, long current_value, long total_cost) {
        if (total_cost >= min_cost) return;
        if (position == 0) {
            if (current_value == 0) min_cost = total_cost;
            return;
        }
        long q = current_value / A[position];
        long diff_neg = Math.abs(q) - 1;
        if (q < 0) diff_neg = -diff_neg;
        long diff_pos = Math.abs(q) + 1;
        if (q < 0) diff_pos = -diff_pos;

        recurse(position - 1, current_value - q * B[position], total_cost + Math.abs(q) * position);
        recurse(position - 1, current_value - diff_neg * B[position], total_cost + Math.abs(diff_neg) * position);
        recurse(position - 1, current_value - diff_pos * B[position], total_cost + Math.abs(diff_pos) * position);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 16; i++) B[i] = B[i - 1] * 10 + 1;
        A[1] = 1;
        for (int i = 2; i <= 16; i++) A[i] = A[i - 1] * 10;
        n = sc.nextLong();
        long temp_num = n;
        int digit_count = 0;
        while (temp_num != 0) {
            digit_count++;
            temp_num /= 10;
        }
        min_cost = Long.MAX_VALUE;
        recurse(digit_count, n, 0);
        recurse(digit_count, B[digit_count + 1] - n, digit_count + 1);
        System.out.println(min_cost);
        sc.close();
    }
}
